  return t;
}

var gArr = draw.group(), gEdge = draw.group(), gHeap = draw.group(),
  gNode = draw.group(), gOver = draw.group(), gCap = draw.group();

/* ---- array bar ---- */
halo(mkText(gArr, 'A', AX - 16, AY + CH / 2, 15, 'middle', '#000', true));
gArr.rect(CW * 10 + 4, CH + 4).move(AX - 2, AY - 2).fill('none').stroke({ color: '#333', width: 1.2 });
var cellRect = {}, cellText = {}, cellG = {};
for (var ci = 1; ci <= 10; ci++) {
  var cg = gArr.group();
  var cx = AX + (ci - 1) * CW;
  cellRect[ci] = cg.rect(CW, CH).move(cx, AY).fill(LIGHT).stroke({ color: '#333', width: 1.1 });
  cellText[ci] = mkText(cg, INIT[ci - 1], cx + CW / 2, AY + CH / 2, 14);
  mkText(gArr, ci, cx + CW / 2, AY + CH + 10, 8.5, 'middle', '#8a8a8a');
  cellG[ci] = cg;
  (function (k) {
