  nodeV[ni] = mkText(g, INIT[ni - 1], pos[0], pos[1] + 0.5, 15);
  var isRight = (ni > 1) && (ni % 2 === 1);
  var lx = pos[0] + (ni === 1 ? 0 : (isRight ? R + 2 : -(R + 2)));
  var ly = pos[1] - (ni === 1 ? R + 11 : R - 2);
  halo(mkText(gNode, ni, lx, ly, 10.5, ni === 1 ? 'middle' : (isRight ? 'start' : 'end'), '#000'));
  nodeG[ni] = g;
  (function (k) {
    g.css('cursor', 'pointer');
