var capLine = mkText(gCap, 'MAX-HEAPIFY(A, 5)', 300, 422, 13, 'middle', '#14507d');
var bannerRect = gCap.rect(300, 20).move(150, 436).radius(4).fill('#e8f5e9').stroke({ color: OK, width: 1 }).opacity(0);
var bannerText = mkText(gCap, '', 300, 446, 10.5, 'middle', OK).opacity(0);
capLine.css('cursor', 'pointer');
capLine.on('click', function () {
  showPopup('Why backwards?', 'MAX-HEAPIFY can only repair a node whose two subtrees are already heaps. Indices ⌊n/2⌋+1 … n are leaves — trivially heaps — so starting at ⌊n/2⌋ and walking down to 1 guarantees that precondition for free at every single call.');
});

var legend = [[DARK, 'none', 'current i'], [LIGHT, '#333', 'other nodes'], ['#fff', CMP, 'compared'], ['#fff', SWP, 'swapped'], ['#fff', OK, 'already a heap']];
var lx0 = 22;
for (var li = 0; li < legend.length; li++) {
  gCap.circle(11).center(lx0, 472).fill(legend[li][0]).stroke(legend[li][1] === 'none' ? { color: '#333', width: 0.8 } : { color: legend[li][1], width: 1.8 });
  mkText(gCap, legend[li][2], lx0 + 9, 472, 9, 'start', '#444');
