}

/* ============================= demo steps =============================== */
var demoSteps = [
  { title: 'Panel (a): start at i = 5', narration: 'A = ⟨4, 1, 3, 2, 16, 9, 10, 14, 8, 7⟩ drawn as a tree. Indices 6..10 are leaves, already trivial heaps, so the first real work is at index 5 (value 16), shaded dark gray.', state: { panelStep: 5, buildRun: 'idle' } },
  { title: 'Write MAX-HEAPIFY', narration: 'In the editor, compare node i with its left and right children, keep the largest, and if it is not i, swap and recurse. Every greater() and swap() you call becomes one animation frame in the tree and the array.', state: { panelStep: 5, buildRun: 'idle' } },
  { title: 'Panel (b): i = 4', narration: 'MAX-HEAPIFY(A, 5) found 16 already larger than its only child 7, so nothing moved. The loop steps to i = 4 (value 2), whose children 14 and 8 both exceed it.', state: { panelStep: 4, buildRun: 'running' } },
  { title: 'Panels (c)–(d): i = 3, then i = 2', narration: '2 sinks below 14, then 3 swaps with 10, then 1 swaps with 16 and keeps sinking. Each call only has to fix the top node, because everything beneath it is already a valid heap.', state: { panelStep: 2, buildRun: 'running' } },
  { title: 'Panel (e): i = 1, the root sifts down', narration: 'The last call starts at the root: 4 must travel two levels, swapping with 16 and then with 7, before the whole tree satisfies the heap property.', state: { panelStep: 1, buildRun: 'running' } },
  { title: 'Panel (f): a max-heap', narration: 'No node is shaded; root 16 is the maximum and every parent dominates its children. Now run the Buggy version that skips the recursive call and watch exactly where the tree diverges.', state: { panelStep: 0, buildRun: 'done' } }
];
var stepIdx = 0;
function applyStep(k) {
