// @FIGURE_CODE_BEGIN
/* ============================ geometry & data ============================ */
var SERIF = 'Georgia, "Times New Roman", Times, serif';
var W = 600, H = 450, R = 19;
/* widened bottom row so index numerals 8 / 9 / 10 never collide */
var NPOS = {
  1: [300, 125], 2: [180, 198], 3: [420, 198],
  4: [110, 271], 5: [250, 271], 6: [355, 271], 7: [485, 271],
  8: [70, 344], 9: [150, 344], 10: [230, 344]
};
var AX = 140, AY = 18, CW = 32, CH = 26;

var INIT = [4, 1, 3, 2, 16, 9, 10, 14, 8, 7];

var PANELS = [
  { letter: '(a)', i: 5, arr: [4, 1, 3, 2, 16, 9, 10, 14, 8, 7] },
  { letter: '(b)', i: 4, arr: [4, 1, 3, 2, 16, 9, 10, 14, 8, 7] },
  { letter: '(c)', i: 3, arr: [4, 1, 3, 14, 16, 9, 10, 2, 8, 7] },
  { letter: '(d)', i: 2, arr: [4, 1, 10, 14, 16, 9, 3, 2, 8, 7] },
  { letter: '(e)', i: 1, arr: [4, 16, 10, 14, 7, 9, 3, 2, 8, 1] },
  { letter: '(f)', i: 0, arr: [16, 14, 10, 8, 7, 9, 3, 2, 4, 1] }
];

var LIGHT = '#e8e8e8', DARK = '#8f8f8f';
var CMP = '#1f77b4', SWP = '#e07b00', BAD = '#c00000', OK = '#2a7d2a';

/* ============================ svg scaffolding ============================ */
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H).attr('preserveAspectRatio', 'xMidYMid meet');

var mkCmp = draw.marker(4, 4, function (a) { a.path('M0,0 L4,2 L0,4 Z').fill(CMP); });
var mkSwpE = draw.marker(4, 4, function (a) { a.path('M0,0 L4,2 L0,4 Z').fill(SWP); });
var mkSwpS = draw.marker(4, 4, function (a) { a.path('M4,0 L0,2 L4,4 Z').fill(SWP); });

function mkText(parent, str, x, y, size, anchor, fill, italic) {
  var t = parent.plain(String(str));
  t.font({ family: SERIF, size: size });
  t.attr({ x: x, y: y, 'text-anchor': anchor || 'middle', 'dominant-baseline': 'central', fill: fill || '#000' });
  if (italic) t.attr('font-style', 'italic');
  return t;
}
function halo(t) {
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.2, 'stroke-linejoin': 'round' });
  return t;
}

var gArr = draw.group(), gArrIdx = draw.group(), gEdge = draw.group(), gHeap = draw.group(),
  gNode = draw.group(), gIdx = draw.group(), gOver = draw.group(), gCap = draw.group();

/* ---- array bar (matches the textbook's single initial array) ---- */
halo(mkText(gArr, 'A', AX - 16, AY + CH / 2, 15, 'middle', '#000', true));
gArr.rect(CW * 10 + 4, CH + 4).move(AX - 2, AY - 2).fill('none').stroke({ color: '#333', width: 1.2 });
var cellRect = {}, cellText = {}, cellG = {};
for (var ci = 1; ci <= 10; ci++) {
  var cg = gArr.group();
  var cx = AX + (ci - 1) * CW;
  cellRect[ci] = cg.rect(CW, CH).move(cx, AY).fill(LIGHT).stroke({ color: '#333', width: 1.1 });
  cellText[ci] = mkText(cg, INIT[ci - 1], cx + CW / 2, AY + CH / 2, 15);
  mkText(gArrIdx, ci, cx + CW / 2, AY + CH + 11, 10.5, 'middle', '#8a8a8a');
  cellG[ci] = cg;
  (function (k) {
    cg.css('cursor', 'pointer');
    cg.on('mousemove', function (e) { showTooltip('A[' + k + '] = ' + curCells[k - 1] + ' — same element as tree node ' + k, e); });
    cg.on('mouseleave', hideTooltip);
    cg.on('click', function () {
      showPopup('Array ↔ tree', 'The heap lives inside the array A: node k is A[k], its children are A[2k] and A[2k+1], its parent A[⌊k/2⌋]. Nothing is ever allocated — BUILD-MAX-HEAP only rearranges A in place. In panel mode this bar shows the original input; run your own code to watch it change.');
    });
  })(ci);
}
gArrIdx.opacity(0);
var arrNote = mkText(gArr, 'initial array', AX + CW * 10 + 14, AY + CH / 2, 10.5, 'start', '#9a9a9a', true);

/* ---- edges ---- */
var edgeL = {};
for (var ei = 2; ei <= 10; ei++) {
  var p = NPOS[Math.floor(ei / 2)], q = NPOS[ei];
  edgeL[ei] = gEdge.line(p[0], p[1], q[0], q[1]).stroke({ color: '#222', width: 1.2 });
}

/* ---- nodes ---- */
var nodeG = {}, nodeC = {}, nodeV = {}, nodeHeap = {}, nodeIdx = {};
for (var ni = 1; ni <= 10; ni++) {
  var pos = NPOS[ni];
  nodeHeap[ni] = gHeap.circle((R + 5) * 2).center(pos[0], pos[1])
    .fill('none').stroke({ color: OK, width: 2 }).opacity(0);
  var g = gNode.group();
  nodeC[ni] = g.circle(R * 2).center(pos[0], pos[1]).fill(LIGHT).stroke({ color: '#333', width: 1.4 });
  nodeV[ni] = mkText(g, INIT[ni - 1], pos[0], pos[1] + 0.5, 15);
  /* index numeral: up-and-outward, 13px, haloed */
  var isRight = (ni > 1) && (ni % 2 === 1);
  var lx, ly, anch;
  if (ni === 1) { lx = pos[0]; ly = pos[1] - R - 10; anch = 'middle'; }
  else if (isRight) { lx = pos[0] + R + 2; ly = pos[1] - R - 2; anch = 'start'; }
  else { lx = pos[0] - R - 2; ly = pos[1] - R - 2; anch = 'end'; }
  nodeIdx[ni] = halo(mkText(gIdx, ni, lx, ly, 13, anch, '#000'));
  nodeG[ni] = g;
  (function (k) {
    g.css('cursor', 'pointer');
    g.on('mousemove', function (e) {
      var kids = [];
      if (2 * k <= curArr.length) kids.push('A[' + (2 * k) + ']=' + curArr[2 * k - 1]);
      if (2 * k + 1 <= curArr.length) kids.push('A[' + (2 * k + 1) + ']=' + curArr[2 * k]);
      showTooltip('node ' + k + ': key ' + curArr[k - 1] + (kids.length ? ' · children ' + kids.join(', ') : ' · leaf'), e);
    });
    g.on('mouseleave', hideTooltip);
    g.on('click', function () {
      showPopup('Node ' + k,
        'Children of node ' + k + ' are ' + (2 * k) + ' and ' + (2 * k + 1) + '; its parent is ' + Math.floor(k / 2) + '. ' +
        'MAX-HEAPIFY(A, ' + k + ') may only be called once both subtrees are already max-heaps — that is exactly why the build loop runs downward from ⌊n/2⌋ to 1.');
    });
  })(ni);
}

/* ---- panel caption ---- */
var capLetter = mkText(gCap, '(a)', 300, 400, 15);
var capLine = mkText(gCap, 'MAX-HEAPIFY(A, 5)', 300, 424, 12.5, 'middle', '#14507d');
capLine.css('cursor', 'pointer');
capLine.on('mousemove', function (e) { showTooltip('Why run the loop backwards? Click to find out.', e); });
capLine.on('mouseleave', hideTooltip);
capLine.on('click', function () {
  showPopup('Why backwards?', 'MAX-HEAPIFY can only repair a node whose two subtrees are already heaps. Indices ⌊n/2⌋+1 … n are leaves — trivially heaps — so starting at ⌊n/2⌋ and walking down to 1 guarantees that precondition for free at every single call.');
});

/* ============================== rendering =============================== */
var curArr = INIT.slice(), curCells = INIT.slice();
var showHeapShade = false;

function edgePts(a, b, pad) {
