    var a = NPOS[s.swapPair[0]], b = NPOS[s.swapPair[1]];
    var ep = edgePts(s.swapPair[0], s.swapPair[1], R + 4);
    var mx = (ep[0] + ep[2]) / 2, my = (ep[1] + ep[3]) / 2;
