  '  function push(kind, ind, msg){ if(frames.length >= MAXF) throw new Error("Frame limit exceeded ("+MAXF+" frames).");',
  '    frames.push({kind:kind, state:arr.slice(), indices:ind.slice(), message:msg, mark:markI, markText:markT, loop:loopI}); }',
  '  function idx(i, name){ i = Number(i);',
  '    if(!isFinite(i) || i !== Math.floor(i) || i < 1 || i > n) throw new Error(name+"(): index "+i+" is outside 1.."+n+".");',
  '    return i; }',
  '  var value = function(i){ i = idx(i,"value"); return arr[i-1]; };',
  '  var left  = function(i){ return 2*Number(i); };',
  '  var right = function(i){ return 2*Number(i)+1; };',
  '  var greater = function(i,j){ chk(); i = idx(i,"greater"); j = idx(j,"greater");',
  '    var res = arr[i-1] > arr[j-1];',
  '    push("compare",[i,j],"compare A["+i+"]="+arr[i-1]+" with A["+j+"]="+arr[j-1]+" -> "+res); return res; };',
  '  var swap = function(i,j){ chk(); i = idx(i,"swap"); j = idx(j,"swap");',
  '    var t = arr[i-1]; arr[i-1] = arr[j-1]; arr[j-1] = t;',
  '    push("swap",[i,j],"swap A["+i+"] <-> A["+j+"]  (now "+arr[i-1]+", "+arr[j-1]+")"); };',
  '  var mark = function(i,text){ chk(); i = idx(i,"mark"); markI = i; markT = String(text==null?"i":text);',
  '    push("mark",[i],"mark node "+i+" as \\"" + markT + "\\"  (A["+i+"]="+arr[i-1]+")"); };',
