var frames = [], fIdx = 0, playing = false, playTimer = null, running = false, violPair = null, finalOk = null;

function setStatus(kind, text) {
  var el = document.getElementById('runStatus');
  var bg = { idle: '#eef1f4', running: '#fff6e0', ok: '#e8f5e9', wrong: '#fbe4e4', error: '#fbe4e4' }[kind] || '#eef1f4';
  var fg = { idle: '#444', running: '#8a5a00', ok: OK, wrong: BAD, error: BAD }[kind] || '#444';
  el.style.background = bg; el.style.color = fg; el.textContent = text;
}
function setBuildState(st) {
  if (mode !== 'panel') return;
  if (st === 'running') setStatus('running', 'BUILD-MAX-HEAP in progress (textbook snapshot)');
  else if (st === 'done') setStatus('ok', 'done — A is a max-heap: every parent ≥ both children');
  else setStatus('idle', 'idle — press Run to trace your own code');
}
function parseArray(str) {
  var parts = String(str).split(/[\s,;]+/).filter(function (s) { return s.length; });
  if (!parts.length || parts.length > 10) return null;
  var out = [];
  for (var i = 0; i < parts.length; i++) { var v = Number(parts[i]); if (!isFinite(v)) return null; out.push(v); }
  return out;
}
function heapViolation(a) {
  for (var i = 1; i <= Math.floor(a.length / 2); i++) {
    if (2 * i <= a.length && a[i - 1] < a[2 * i - 1]) return [i, 2 * i];
    if (2 * i + 1 <= a.length && a[i - 1] < a[2 * i]) return [i, 2 * i + 1];
  }
  return null;
}

function trigger_buildRun() {
  if (running) return;
  var code = document.getElementById('heapifyEditorCode').value;
  var arr = parseArray(document.getElementById('heapifyEditorInput').value);
  if (!arr) { setStatus('error', 'Could not read A — give 1 to 10 comma-separated numbers.'); return; }
  running = true; violPair = null; finalOk = null;
  var btn = document.getElementById('buildRunBtn');
  btn.disabled = true; btn.textContent = '… running';
  mode = 'frames'; stopPlay();
  setStatus('running', 'running your maxHeapify in a sandbox…');
  var url = URL.createObjectURL(new Blob([WORKER_SRC], { type: 'text/javascript' }));
  var w = new Worker(url);
  var done = function () { try { w.terminate(); } catch (e) { } URL.revokeObjectURL(url); running = false; btn.disabled = false; btn.textContent = '▶ Run BUILD-MAX-HEAP'; };
  var timer = setTimeout(function () {
    done();
    frames = [{ kind: 'error', state: arr.slice(), indices: [], message: 'ERROR: timed out (>2 s) — probable infinite loop.', mark: -1, markText: '', loop: 1 }];
    buildLog(); showFrame(0); setStatus('error', 'timed out — infinite recursion or loop?');
  }, 2200);
  w.onerror = function (ev) {
    clearTimeout(timer); done();
    frames = [{ kind: 'error', state: arr.slice(), indices: [], message: 'ERROR: ' + (ev.message || 'syntax error in your code'), mark: -1, markText: '', loop: 1 }];
    buildLog(); showFrame(0); setStatus('error', 'error: ' + (ev.message || 'syntax error'));
  };
  w.onmessage = function (ev) {
    clearTimeout(timer); done();
    var d = ev.data;
    frames = d.frames && d.frames.length ? d.frames : [{ kind: 'error', state: arr.slice(), indices: [], message: 'ERROR: no frames recorded — your code called no API ops.', mark: -1, markText: '', loop: 1 }];
    buildLog();
    if (!d.ok) { finalOk = false; setStatus('error', 'error: ' + d.error); }
    else {
      var fin = frames[frames.length - 1].state;
      var v = heapViolation(fin);
      if (v) { finalOk = false; violPair = v; setStatus('wrong', 'wrong answer — A[' + v[0] + ']=' + fin[v[0] - 1] + ' < A[' + v[1] + ']=' + fin[v[1] - 1] + ' (not a max-heap)'); }
      else { finalOk = true; setStatus('ok', 'correct — every parent ≥ both children, root = ' + fin[0]); }
    }
    showFrame(0);
    pbPlay();
  };
  w.postMessage({ arr: arr, code: code });
}

function buildLog() {
  var el = document.getElementById('opLog');
  el.innerHTML = '';
  frames.forEach(function (f, k) {
    var s = document.createElement('span');
    s.style.cssText = 'display:block;padding:1px 3px;border-radius:2px;cursor:pointer;white-space:normal;' +
      (f.kind === 'loop' ? 'color:#14507d;font-weight:600;' : f.kind === 'swap' ? 'color:#b45f00;' : f.kind === 'error' ? 'color:#c00000;font-weight:600;' : 'color:#444;');
    s.textContent = (k + 1) + '. ' + f.message;
    s.onclick = function () { stopPlay(); showFrame(k); };
    el.appendChild(s);
  });
}

function showFrame(k) {
  if (!frames.length) return;
  mode = 'frames';
  fIdx = Math.max(0, Math.min(frames.length - 1, k));
  var f = frames[fIdx];
  var last = (fIdx === frames.length - 1);
  renderState({
    arr: f.state, cells: f.state, liveCells: true, n: f.state.length,
    current: f.mark > 0 ? f.mark : 0,
    currentLabel: f.markText || 'i',
    compared: f.kind === 'compare' ? f.indices : null,
    swapPair: f.kind === 'swap' ? f.indices : null,
    violation: (last && violPair) ? violPair : null,
    heapFrom: (f.loop && f.loop <= f.state.length) ? f.loop + 1 : null,
    letter: f.kind === 'done' ? '(f)' : '',
    caption: f.kind === 'loop' ? 'MAX-HEAPIFY(A, ' + f.indices[0] + ')'
      : f.kind === 'done' ? 'BUILD-MAX-HEAP finished'
        : f.kind === 'error' ? 'execution stopped'
          : (f.loop ? 'MAX-HEAPIFY(A, ' + f.loop + ')' : '')
  });
  document.getElementById('frameCounter').textContent = (fIdx + 1) + ' of ' + frames.length;
  document.getElementById('frameCaption').textContent = f.message;
  var log = document.getElementById('opLog');
  for (var j = 0; j < log.children.length; j++) log.children[j].style.background = (j === fIdx) ? '#d8ecff' : 'transparent';
  var cur = log.children[fIdx];
  if (cur) log.scrollTop = cur.offsetTop - log.clientHeight / 2;
}

