// @FIGURE_CODE_BEGIN
/* ============================ geometry & data ============================ */
var SERIF = 'Georgia, "Times New Roman", Times, serif';
var W = 600, H = 450, R = 19;
/* widened bottom row so index numerals 8 / 9 / 10 never collide */
var NPOS = {
  1: [300, 125], 2: [180, 198], 3: [420, 198],
  4: [110, 271], 5: [250, 271], 6: [355, 271], 7: [485, 271],
  8: [70, 344], 9: [150, 344], 10: [230, 344]
};
var AX = 140, AY = 18, CW = 32, CH = 26;

var INIT = [4, 1, 3, 2, 16, 9, 10, 14, 8, 7];

var PANELS = [
  { letter: '(a)', i: 5, arr: [4, 1, 3, 2, 16, 9, 10, 14, 8, 7] },
  { letter: '(b)', i: 4, arr: [4, 1, 3, 2, 16, 9, 10, 14, 8, 7] },
  { letter: '(c)', i: 3, arr: [4, 1, 3, 14, 16, 9, 10, 2, 8, 7] },
  { letter: '(d)', i: 2, arr: [4, 1, 10, 14, 16, 9, 3, 2, 8, 7] },
  { letter: '(e)', i: 1, arr: [4, 16, 10, 14, 7, 9, 3, 2, 8, 1] },
  { letter: '(f)', i: 0, arr: [16, 14, 10, 8, 7, 9, 3, 2, 4, 1] }
];

var LIGHT = '#e8e8e8', DARK = '#8f8f8f';
var CMP = '#1f77b4', SWP = '#e07b00', BAD = '#c00000', OK = '#2a7d2a';

/* ============================ svg scaffolding ============================ */
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H).attr('preserveAspectRatio', 'xMidYMid meet');

var mkCmp = draw.marker(4, 4, function (a) { a.path('M0,0 L4,2 L0,4 Z').fill(CMP); });
var mkSwpE = draw.marker(4, 4, function (a) { a.path('M0,0 L4,2 L0,4 Z').fill(SWP); });
var mkSwpS = draw.marker(4, 4, function (a) { a.path('M4,0 L0,2 L4,4 Z').fill(SWP); });

function mkText(parent, str, x, y, size, anchor, fill, italic) {
  var t = parent.plain(String(str));
  t.font({ family: SERIF, size: size });
  t.attr({ x: x, y: y, 'text-anchor': anchor || 'middle', 'dominant-baseline': 'central', fill: fill || '#000' });
  if (italic) t.attr('font-style', 'italic');
  return t;
}
function halo(t) {
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.2, 'stroke-linejoin': 'round' });
  return t;
}

var gArr = draw.group(), gArrIdx = draw.group(), gEdge = draw.group(), gHeap = draw.group(),
  gNode = draw.group(), gIdx = draw.group(), gOver = draw.group(), gCap = draw.group();

/* ---- array bar (matches the textbook's single initial array) ---- */
halo(mkText(gArr, 'A', AX - 16, AY + CH / 2, 15, 'middle', '#000', true));
gArr.rect(CW * 10 + 4, CH + 4).move(AX - 2, AY - 2).fill('none').stroke({ color: '#333', width: 1.2 });
var cellRect = {}, cellText = {}, cellG = {};
for (var ci = 1; ci <= 10; ci++) {
  var cg = gArr.group();
  var cx = AX + (ci - 1) * CW;
  cellRect[ci] = cg.rect(CW, CH).move(cx, AY).fill(LIGHT).stroke({ color: '#333', width: 1.1 });
  cellText[ci] = mkText(cg, INIT[ci - 1], cx + CW / 2, AY + CH / 2, 15);
  mkText(gArrIdx, ci, cx + CW / 2, AY + CH + 11, 10.5, 'middle', '#8a8a8a');
  cellG[ci] = cg;
  (function (k) {
    cg.css('cursor', 'pointer');
    cg.on('mousemove', function (e) { showTooltip('A[' + k + '] = ' + curCells[k - 1] + ' — same element as tree node ' + k, e); });
    cg.on('mouseleave', hideTooltip);
    cg.on('click', function () {
      showPopup('Array ↔ tree', 'The heap lives inside the array A: node k is A[k], its children are A[2k] and A[2k+1], its parent A[⌊k/2⌋]. Nothing is ever allocated — BUILD-MAX-HEAP only rearranges A in place. In panel mode this bar shows the original input; run your own code to watch it change.');
    });
  })(ci);
}
gArrIdx.opacity(0);
var arrNote = mkText(gArr, 'initial array', AX + CW * 10 + 14, AY + CH / 2, 10.5, 'start', '#9a9a9a', true);

/* ---- edges ---- */
var edgeL = {};
for (var ei = 2; ei <= 10; ei++) {
  var p = NPOS[Math.floor(ei / 2)], q = NPOS[ei];
  edgeL[ei] = gEdge.line(p[0], p[1], q[0], q[1]).stroke({ color: '#222', width: 1.2 });
}

/* ---- nodes ---- */
var nodeG = {}, nodeC = {}, nodeV = {}, nodeHeap = {}, nodeIdx = {};
for (var ni = 1; ni <= 10; ni++) {
  var pos = NPOS[ni];
  nodeHeap[ni] = gHeap.circle((R + 5) * 2).center(pos[0], pos[1])
    .fill('none').stroke({ color: OK, width: 2 }).opacity(0);
  var g = gNode.group();
  nodeC[ni] = g.circle(R * 2).center(pos[0], pos[1]).fill(LIGHT).stroke({ color: '#333', width: 1.4 });
  nodeV[ni] = mkText(g, INIT[ni - 1], pos[0], pos[1] + 0.5, 15);
  /* index numeral: up-and-outward, 13px, haloed */
  var isRight = (ni > 1) && (ni % 2 === 1);
  var lx, ly, anch;
  if (ni === 1) { lx = pos[0]; ly = pos[1] - R - 10; anch = 'middle'; }
  else if (isRight) { lx = pos[0] + R + 2; ly = pos[1] - R - 2; anch = 'start'; }
  else { lx = pos[0] - R - 2; ly = pos[1] - R - 2; anch = 'end'; }
  nodeIdx[ni] = halo(mkText(gIdx, ni, lx, ly, 13, anch, '#000'));
  nodeG[ni] = g;
  (function (k) {
    g.css('cursor', 'pointer');
    g.on('mousemove', function (e) {
      var kids = [];
      if (2 * k <= curArr.length) kids.push('A[' + (2 * k) + ']=' + curArr[2 * k - 1]);
      if (2 * k + 1 <= curArr.length) kids.push('A[' + (2 * k + 1) + ']=' + curArr[2 * k]);
      showTooltip('node ' + k + ': key ' + curArr[k - 1] + (kids.length ? ' · children ' + kids.join(', ') : ' · leaf'), e);
    });
    g.on('mouseleave', hideTooltip);
    g.on('click', function () {
      showPopup('Node ' + k,
        'Children of node ' + k + ' are ' + (2 * k) + ' and ' + (2 * k + 1) + '; its parent is ' + Math.floor(k / 2) + '. ' +
        'MAX-HEAPIFY(A, ' + k + ') may only be called once both subtrees are already max-heaps — that is exactly why the build loop runs downward from ⌊n/2⌋ to 1.');
    });
  })(ni);
}

/* ---- panel caption ---- */
var capLetter = mkText(gCap, '(a)', 300, 400, 15);
var capLine = mkText(gCap, 'MAX-HEAPIFY(A, 5)', 300, 424, 12.5, 'middle', '#14507d');
capLine.css('cursor', 'pointer');
capLine.on('mousemove', function (e) { showTooltip('Why run the loop backwards? Click to find out.', e); });
capLine.on('mouseleave', hideTooltip);
capLine.on('click', function () {
  showPopup('Why backwards?', 'MAX-HEAPIFY can only repair a node whose two subtrees are already heaps. Indices ⌊n/2⌋+1 … n are leaves — trivially heaps — so starting at ⌊n/2⌋ and walking down to 1 guarantees that precondition for free at every single call.');
});

/* ============================== rendering =============================== */
var curArr = INIT.slice(), curCells = INIT.slice();
var showHeapShade = false;

function edgePts(a, b, pad) {
  var p = NPOS[a], q = NPOS[b];
  var dx = q[0] - p[0], dy = q[1] - p[1], d = Math.sqrt(dx * dx + dy * dy) || 1;
  return [p[0] + dx / d * pad, p[1] + dy / d * pad, q[0] - dx / d * pad, q[1] - dy / d * pad];
}

function renderState(s) {
  var arr = s.arr, n = s.n || arr.length;
  var cells = s.cells || arr;
  curArr = arr; curCells = cells;
  gOver.clear();
  for (var i = 1; i <= 10; i++) {
    var on = i <= n;
    nodeG[i].opacity(on ? 1 : 0);
    nodeIdx[i].opacity(on ? 1 : 0);
    if (edgeL[i]) edgeL[i].opacity(on ? 1 : 0);
    cellG[i].opacity(i <= cells.length ? 1 : 0);
    nodeHeap[i].opacity(0);
    if (i <= cells.length) cellText[i].plain(String(cells[i - 1]));
    if (!on) continue;
    nodeV[i].plain(String(arr[i - 1]));
    var fill = LIGHT, stroke = '#333', sw = 1.4, cfill = LIGHT, cstroke = '#333', csw = 1.1;
    if (i === s.current) fill = DARK;
    if (s.compared && s.compared.indexOf(i) >= 0) { stroke = CMP; sw = 3; }
    if (s.swapPair && s.swapPair.indexOf(i) >= 0) { stroke = SWP; sw = 3; }
    if (s.violation && s.violation.indexOf(i) >= 0) { stroke = BAD; sw = 3; fill = '#f6d6d6'; }
    if (s.liveCells) {
      cfill = (i === s.current) ? DARK : LIGHT;
      if (stroke !== '#333') { cstroke = stroke; csw = 2.2; cfill = (i === s.current) ? DARK : '#fff'; }
      if (s.violation && s.violation.indexOf(i) >= 0) cfill = '#f6d6d6';
    }
    nodeC[i].fill(fill).stroke({ color: stroke, width: sw });
    cellRect[i].fill(cfill).stroke({ color: cstroke, width: csw });
    if (showHeapShade && s.heapFrom && i >= s.heapFrom && i <= n) nodeHeap[i].opacity(0.6);
  }
  if (s.current > 0 && s.current <= n) {
    var pc = NPOS[s.current];
    var right = (s.current === 3 || s.current === 7);
    halo(mkText(gOver, s.currentLabel || 'i',
      pc[0] + (right ? R + 6 : -(R + 6)), pc[1] + 1, 14, right ? 'start' : 'end', '#000', true));
  }
  if (s.compared && s.compared.length === 2) {
    var e = edgePts(s.compared[0], s.compared[1], R + 3);
    gOver.line(e[0], e[1], e[2], e[3]).stroke({ color: CMP, width: 1.8 }).marker('end', mkCmp);
  }
  if (s.swapPair && s.swapPair.length === 2) {
    var a = NPOS[s.swapPair[0]], b = NPOS[s.swapPair[1]];
    var ep = edgePts(s.swapPair[0], s.swapPair[1], R + 4);
    var mx = (ep[0] + ep[2]) / 2, my = (ep[1] + ep[3]) / 2;
    var dx = b[0] - a[0], dy = b[1] - a[1], d = Math.sqrt(dx * dx + dy * dy) || 1;
    var cxp = mx - dy / d * d * 0.3, cyp = my + dx / d * d * 0.3;
    gOver.path('M' + ep[0] + ',' + ep[1] + ' Q' + cxp + ',' + cyp + ' ' + ep[2] + ',' + ep[3])
      .fill('none').stroke({ color: SWP, width: 1.8 }).marker('start', mkSwpS).marker('end', mkSwpE);
  }
  arrNote.opacity(s.liveCells ? 0 : 1);
  capLetter.plain(s.letter || '');
  capLine.plain(s.caption || '');
}

/* ============================== panel mode ============================== */
var mode = 'panel';
function toggle_heapShade(on) { showHeapShade = on; redraw(); }
function toggle_arrIdx(on) { gArrIdx.opacity(on ? 1 : 0); }
function redraw() { if (mode === 'panel') update_panelStep(+document.getElementById('panelStepInput').value); else showFrame(fIdx); }

function update_panelStep(v) {
  stopPlay();
  mode = 'panel';
  var p = PANELS[5 - v];
  document.getElementById('panelStepVal').value = v + '  ' + p.letter;
  renderState({
    arr: p.arr, cells: INIT, liveCells: false, n: 10,
    current: p.i, currentLabel: 'i', letter: p.letter,
    heapFrom: p.i + 1,
    caption: p.i > 0 ? 'MAX-HEAPIFY(A, ' + p.i + ')' : 'BUILD-MAX-HEAP finished'
  });
}

/* ============================= demo steps =============================== */
var demoSteps = [
  { title: 'Panel (a): start at i = 5', narration: 'A = ⟨4, 1, 3, 2, 16, 9, 10, 14, 8, 7⟩ drawn as a tree. Indices 6..10 are leaves, already trivial heaps, so the first real work is at index 5 (value 16), shaded dark gray.', state: { panelStep: 5, buildRun: 'idle' } },
  { title: 'Write MAX-HEAPIFY', narration: 'In the editor, compare node i with its left and right children, keep the largest, and if it is not i, swap and recurse. Every greater() and swap() you call becomes one animation frame in the tree and the array.', state: { panelStep: 5, buildRun: 'idle' } },
  { title: 'Panel (b): i = 4', narration: 'MAX-HEAPIFY(A, 5) found 16 already larger than its only child 7, so nothing moved. The loop steps to i = 4 (value 2), whose children 14 and 8 both exceed it.', state: { panelStep: 4, buildRun: 'running' } },
  { title: 'Panels (c)–(d): i = 3, then i = 2', narration: '2 sinks below 14, then 3 swaps with 10, then 1 swaps with 16 and keeps sinking. Each call only has to fix the top node, because everything beneath it is already a valid heap.', state: { panelStep: 2, buildRun: 'running' } },
  { title: 'Panel (e): i = 1, the root sifts down', narration: 'The last call starts at the root: 4 must travel two levels, swapping with 16 and then with 7, before the whole tree satisfies the heap property.', state: { panelStep: 1, buildRun: 'running' } },
  { title: 'Panel (f): a max-heap', narration: 'No node is shaded; root 16 is the maximum and every parent dominates its children. Now run the Buggy version that skips the recursive call and watch exactly where the tree diverges.', state: { panelStep: 0, buildRun: 'done' } }
];
var stepIdx = 0;
function applyStep(k) {
  stepIdx = (k + demoSteps.length) % demoSteps.length;
  var s = demoSteps[stepIdx];
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' / ' + demoSteps.length;
  var sl = document.getElementById('panelStepInput');
  sl.value = s.state.panelStep;
  update_panelStep(+s.state.panelStep);
  setBuildState(s.state.buildRun);
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

/* ============================ code samples ============================== */
var CODE = {
  sample: 'function maxHeapify(i, heapSize) {\n  mark(i, \'i\');\n  const l = left(i);\n  const r = right(i);\n  let largest = i;\n  if (l <= heapSize && greater(l, largest)) largest = l;\n  if (r <= heapSize && greater(r, largest)) largest = r;\n  if (largest !== i) {\n    swap(i, largest);\n    maxHeapify(largest, heapSize);\n  }\n}',
  buggy: 'function maxHeapify(i, heapSize) {\n  mark(i, \'i\');\n  const l = left(i);\n  const r = right(i);\n  let largest = i;\n  if (l <= heapSize && greater(l, largest)) largest = l;\n  if (r <= heapSize && greater(r, largest)) largest = r;\n  if (largest !== i) {\n    swap(i, largest);\n    // BUG: no recursive call - the demoted key stops sinking\n    // after one level, so 4 lands at index 2 and stays there.\n  }\n}',
  starter: 'function maxHeapify(i, heapSize) {\n  mark(i, \'i\');\n  // TODO: compare value(i) with its children left(i) and right(i),\n  // keep the largest index, and if it is not i, swap(i, largest)\n  // and recurse on largest.\n}'
};
function loadSample(which) {
  document.getElementById('heapifyEditorCode').value = CODE[which];
  ['Sample', 'Buggy', 'Starter'].forEach(function (t) {
    document.getElementById('tab' + t).classList.toggle('active', t.toLowerCase() === which);
  });
}

/* ============================== worker ================================= */
var WORKER_SRC = [
  'self.onmessage = function(e){',
  '  var arr = e.data.arr.slice(); var n = arr.length; var code = e.data.code;',
  '  var frames = []; var MAXF = 1500, MAXOPS = 4000, ops = 0, t0 = Date.now();',
  '  var markI = -1, markT = "", loopI = n + 1;',
  '  function chk(){ if(++ops > MAXOPS) throw new Error("Operation limit exceeded ("+MAXOPS+") - probable infinite loop or missing base case.");',
  '                  if(Date.now()-t0 > 1500) throw new Error("Time limit exceeded (1.5 s) - probable infinite loop."); }',
  '  function push(kind, ind, msg){ if(frames.length >= MAXF) throw new Error("Frame limit exceeded ("+MAXF+" frames).");',
  '    frames.push({kind:kind, state:arr.slice(), indices:ind.slice(), message:msg, mark:markI, markText:markT, loop:loopI}); }',
  '  function idx(i, name){ i = Number(i);',
  '    if(!isFinite(i) || i !== Math.floor(i) || i < 1 || i > n) throw new Error(name+"(): index "+i+" is outside 1.."+n+".");',
  '    return i; }',
  '  var value = function(i){ i = idx(i,"value"); return arr[i-1]; };',
  '  var left  = function(i){ return 2*Number(i); };',
  '  var right = function(i){ return 2*Number(i)+1; };',
  '  var greater = function(i,j){ chk(); i = idx(i,"greater"); j = idx(j,"greater");',
  '    var res = arr[i-1] > arr[j-1];',
  '    push("compare",[i,j],"compare A["+i+"]="+arr[i-1]+" with A["+j+"]="+arr[j-1]+" -> "+res); return res; };',
  '  var swap = function(i,j){ chk(); i = idx(i,"swap"); j = idx(j,"swap");',
  '    var t = arr[i-1]; arr[i-1] = arr[j-1]; arr[j-1] = t;',
  '    push("swap",[i,j],"swap A["+i+"] <-> A["+j+"]  (now "+arr[i-1]+", "+arr[j-1]+")"); };',
  '  var mark = function(i,text){ chk(); i = idx(i,"mark"); markI = i; markT = String(text==null?"i":text);',
  '    push("mark",[i],"mark node "+i+" as \\"" + markT + "\\"  (A["+i+"]="+arr[i-1]+")"); };',
  '  var out;',
  '  try {',
  '    var factory = new Function("value","left","right","greater","swap","mark",',
  '      code + "\\n;return typeof maxHeapify === \\"function\\" ? maxHeapify : null;");',
  '    var fn = factory(value,left,right,greater,swap,mark);',
  '    if(!fn) throw new Error("No function named maxHeapify(i, heapSize) was defined - check the entry point name.");',
  '    for(var i = Math.floor(n/2); i >= 1; i--){',
  '      loopI = i; markI = i; markT = "i";',
  '      push("loop",[i],"BUILD-MAX-HEAP: i = "+i+"  ->  MAX-HEAPIFY(A, "+i+")");',
  '      fn(i, n);',
  '    }',
  '    loopI = 1; markI = -1; markT = "";',
  '    push("done",[],"BUILD-MAX-HEAP complete.");',
  '    out = {ok:true, frames:frames};',
  '  } catch(err){',
  '    frames.push({kind:"error", state:arr.slice(), indices:[], mark:-1, markText:"", loop:loopI,',
  '      message:"ERROR: " + ((err && err.message) ? err.message : String(err))});',
  '    out = {ok:false, frames:frames, error:((err && err.message) ? err.message : String(err))};',
  '  }',
  '  self.postMessage(out);',
  '};'
].join('\n');

/* ============================ run & playback ============================ */
var frames = [], fIdx = 0, playing = false, playTimer = null, running = false, violPair = null, finalOk = null;

function setStatus(kind, text) {
  var el = document.getElementById('runStatus');
  var bg = { idle: '#eef1f4', running: '#fff6e0', ok: '#e8f5e9', wrong: '#fbe4e4', error: '#fbe4e4' }[kind] || '#eef1f4';
  var fg = { idle: '#444', running: '#8a5a00', ok: OK, wrong: BAD, error: BAD }[kind] || '#444';
  el.style.background = bg; el.style.color = fg; el.textContent = text;
}
function setBuildState(st) {
  if (mode !== 'panel') return;
  if (st === 'running') setStatus('running', 'BUILD-MAX-HEAP in progress (textbook snapshot)');
  else if (st === 'done') setStatus('ok', 'done — A is a max-heap: every parent ≥ both children');
  else setStatus('idle', 'idle — press Run to trace your own code');
}
function parseArray(str) {
  var parts = String(str).split(/[\s,;]+/).filter(function (s) { return s.length; });
  if (!parts.length || parts.length > 10) return null;
  var out = [];
  for (var i = 0; i < parts.length; i++) { var v = Number(parts[i]); if (!isFinite(v)) return null; out.push(v); }
  return out;
}
function heapViolation(a) {
  for (var i = 1; i <= Math.floor(a.length / 2); i++) {
    if (2 * i <= a.length && a[i - 1] < a[2 * i - 1]) return [i, 2 * i];
    if (2 * i + 1 <= a.length && a[i - 1] < a[2 * i]) return [i, 2 * i + 1];
  }
  return null;
}

function trigger_buildRun() {
  if (running) return;
  var code = document.getElementById('heapifyEditorCode').value;
  var arr = parseArray(document.getElementById('heapifyEditorInput').value);
  if (!arr) { setStatus('error', 'Could not read A — give 1 to 10 comma-separated numbers.'); return; }
  running = true; violPair = null; finalOk = null;
  var btn = document.getElementById('buildRunBtn');
  btn.disabled = true; btn.textContent = '… running';
  mode = 'frames'; stopPlay();
  setStatus('running', 'running your maxHeapify in a sandbox…');
  var url = URL.createObjectURL(new Blob([WORKER_SRC], { type: 'text/javascript' }));
  var w = new Worker(url);
  var done = function () { try { w.terminate(); } catch (e) { } URL.revokeObjectURL(url); running = false; btn.disabled = false; btn.textContent = '▶ Run BUILD-MAX-HEAP'; };
  var timer = setTimeout(function () {
    done();
    frames = [{ kind: 'error', state: arr.slice(), indices: [], message: 'ERROR: timed out (>2 s) — probable infinite loop.', mark: -1, markText: '', loop: 1 }];
    buildLog(); showFrame(0); setStatus('error', 'timed out — infinite recursion or loop?');
  }, 2200);
  w.onerror = function (ev) {
    clearTimeout(timer); done();
    frames = [{ kind: 'error', state: arr.slice(), indices: [], message: 'ERROR: ' + (ev.message || 'syntax error in your code'), mark: -1, markText: '', loop: 1 }];
    buildLog(); showFrame(0); setStatus('error', 'error: ' + (ev.message || 'syntax error'));
  };
  w.onmessage = function (ev) {
    clearTimeout(timer); done();
    var d = ev.data;
    frames = d.frames && d.frames.length ? d.frames : [{ kind: 'error', state: arr.slice(), indices: [], message: 'ERROR: no frames recorded — your code called no API ops.', mark: -1, markText: '', loop: 1 }];
    buildLog();
    if (!d.ok) { finalOk = false; setStatus('error', 'error: ' + d.error); }
    else {
      var fin = frames[frames.length - 1].state;
      var v = heapViolation(fin);
      if (v) { finalOk = false; violPair = v; setStatus('wrong', 'wrong answer — A[' + v[0] + ']=' + fin[v[0] - 1] + ' < A[' + v[1] + ']=' + fin[v[1] - 1] + ' (not a max-heap)'); }
      else { finalOk = true; setStatus('ok', 'correct — every parent ≥ both children, root = ' + fin[0]); }
    }
    showFrame(0);
    pbPlay();
  };
  w.postMessage({ arr: arr, code: code });
}

function buildLog() {
  var el = document.getElementById('opLog');
  el.innerHTML = '';
  frames.forEach(function (f, k) {
    var s = document.createElement('span');
    s.style.cssText = 'display:block;padding:1px 3px;border-radius:2px;cursor:pointer;white-space:normal;' +
      (f.kind === 'loop' ? 'color:#14507d;font-weight:600;' : f.kind === 'swap' ? 'color:#b45f00;' : f.kind === 'error' ? 'color:#c00000;font-weight:600;' : 'color:#444;');
    s.textContent = (k + 1) + '. ' + f.message;
    s.onclick = function () { stopPlay(); showFrame(k); };
    el.appendChild(s);
  });
}

function showFrame(k) {
  if (!frames.length) return;
  mode = 'frames';
  fIdx = Math.max(0, Math.min(frames.length - 1, k));
  var f = frames[fIdx];
  var last = (fIdx === frames.length - 1);
  renderState({
    arr: f.state, cells: f.state, liveCells: true, n: f.state.length,
    current: f.mark > 0 ? f.mark : 0,
    currentLabel: f.markText || 'i',
    compared: f.kind === 'compare' ? f.indices : null,
    swapPair: f.kind === 'swap' ? f.indices : null,
    violation: (last && violPair) ? violPair : null,
    heapFrom: (f.loop && f.loop <= f.state.length) ? f.loop + 1 : null,
    letter: f.kind === 'done' ? '(f)' : '',
    caption: f.kind === 'loop' ? 'MAX-HEAPIFY(A, ' + f.indices[0] + ')'
      : f.kind === 'done' ? 'BUILD-MAX-HEAP finished'
        : f.kind === 'error' ? 'execution stopped'
          : (f.loop ? 'MAX-HEAPIFY(A, ' + f.loop + ')' : '')
  });
  document.getElementById('frameCounter').textContent = (fIdx + 1) + ' of ' + frames.length;
  document.getElementById('frameCaption').textContent = f.message;
  var log = document.getElementById('opLog');
  for (var j = 0; j < log.children.length; j++) log.children[j].style.background = (j === fIdx) ? '#d8ecff' : 'transparent';
  var cur = log.children[fIdx];
  if (cur) log.scrollTop = cur.offsetTop - log.clientHeight / 2;
}

function pbFirst() { stopPlay(); showFrame(0); }
function pbPrev() { stopPlay(); showFrame(fIdx - 1); }
function pbNext() { stopPlay(); showFrame(fIdx + 1); }
function stopPlay() { playing = false; if (playTimer) { clearInterval(playTimer); playTimer = null; } var b = document.getElementById('pbPlayBtn'); if (b) b.textContent = '▶'; }
function pbPlay() {
  if (!frames.length) return;
  stopPlay(); playing = true;
  mode = 'frames';
  document.getElementById('pbPlayBtn').textContent = '❚❚';
  var sp = +document.getElementById('speedInput').value;
  playTimer = setInterval(function () {
    if (fIdx >= frames.length - 1) { stopPlay(); return; }
    showFrame(fIdx + 1);
  }, 1150 - sp * 100);
}
function pbToggle() { if (playing) stopPlay(); else pbPlay(); }

/* ================================ init ================================= */
loadSample('sample');
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

